{"command": "python3 - <<'EOF'
import glob, json, re, collections
levels=collections.Counter(); msgs=collections.Counter(); anomalies=[]
for f in glob.glob('logs/*'):
    for i,line in enumerate(open(f),1):
        line=line.rstrip('\n')
        if not line.strip(): 
            anomalies.append((f,i,'blank')); continue
        if f.endswith('.jsonl'):
            try:
                o=json.loads(line)
            except Exception as e:
                anomalies.append((f,i,'badjson',line[:120])); continue
            lvl=o.get('level'); msg=o.get('msg','')
        else:
            m=re.match(r'^(\S+)\s+(\S+)\s+(\[[^\]]+\])\s+(.*)$',line)
            if not m:
                anomalies.append((f,i,'unmatched',line[:150])); continue
            lvl=m.group(2); msg=m.group(5)
        levels[lvl]+=1
        # normalize msg to first couple words
        key=' '.join(msg.split()[:3])
        key=re.sub(r'user=\S+','user=X',key)
        msgs[key]+=1
print("LEVELS:",levels)
print("\nMSG patterns:")
for k,v in msgs.most_common(): print(v,repr(k))
print("\nANOMALIES:",len(anomalies))
for a in anomalies[:40]: print(a)
EOF", "description": "Survey levels, message patterns, anomalies"}

