{"command": "python3 - <<'EOF'
import glob, json, re, collections
rows=[]
for f in glob.glob('logs/*'):
    for i,line in enumerate(open(f),1):
        line=line.rstrip('\n')
        if f.endswith('.jsonl'):
            o=json.loads(line); ts=o.get('ts'); lvl=o.get('level'); svc=o.get('service'); msg=o.get('msg','')
        else:
            m=re.match(r'^(\S+)\s+(\S+)\s+\[([^\]]+)\]\s+(.*)$',line)
            ts,lvl,svc,msg=m.group(1),m.group(2),m.group(3),m.group(4)
        rows.append((ts,lvl,svc,msg,f))
print("level x service:")
c=collections.Counter((r[2],r[1]) for r in rows)
for s in sorted(set(r[2] for r in rows)):
    print(s, {l:c[(s,l)] for l in ['INFO','WARN','ERROR']})
print("\nfile service vs event service mismatches:")
mm=[r for r in rows if not r[4].split('/')[-1].startswith(r[2]+'-')]
print(len(mm))
print("\nlogin failed by level, service:")
c=collections.Counter((r[3].split()[0]+' '+r[3].split()[1] if len(r[3].split())>1 else r[3],r[1],r[2]) for r in rows if 'login failed' in r[3].lower())
for k,v in c.items(): print(v,k)
print("\nall db timeout lines:")
for r in rows:
    if 'db timeout' in r[3].lower(): print(r[:4])
print("\nmsg texts containing db:")
for r in rows:
    if 'db' in r[3].lower(): pass
print(set(r[3] for r in rows if 'timeout' in r[3].lower()))
print("\nlatency extraction issues:")
bad=[]; vals=[]
for r in rows:
    if 'request done' in r[3].lower():
        m=re.search(r'latency_ms=(-?\d+)',r[3])
        if not m: bad.append(r)
        else: vals.append(int(m.group(1)))
print("bad",len(bad),"count",len(vals),"min/max",min(vals),max(vals))
for b in bad[:10]: print(b[:4])
EOF", "description": "Analyze service/level breakdown and event specifics"}

