import glob, json, re, collections
errs=collections.Counter(); warn=collections.Counter()
for f in glob.glob('logs/*'):
    for line in open(f):
        line=line.rstrip('\n')
        if f.endswith('.jsonl'):
            o=json.loads(line); lvl=o['level']; svc=o['service']; msg=o['msg']
        else:
            m=re.match(r'^(\S+)\s+(\S+)\s+\[([^\]]+)\]\s+(.*)$',line)
